#!/bin/bash
# Generated by must-gather-sos <version>
# Catalog: <ref> @ <commit>
# Plugins: core, service_logs
#
# Upstream's gather script uses paths relative to the pod's working directory
# ('must-gather'), while some plugins use '../must-gather'. Both resolve to
# /must-gather only when the working directory is /, which is what the
# must-gather image provides; cd here makes that explicit rather than assumed.
cd / || exit 1

export REDUCE_LOGS=compress_logs,skip_rotated_logs

# shellcheck source=/dev/null
source /usr/bin/common.sh
get_log_collection_args

mkdir -p /must-gather
{
	echo "openshift/must-gather"
	# shellcheck source=/dev/null
	. /usr/bin/version && version
	echo "must-gather-sos <version>"
} >/must-gather/version

# One line per plugin: name rc seconds. Read back by must-gather-sos to build
# manifest.json once the data has been copied out.
: >/must-gather/must-gather-sos-plugins.log

run_plugin() {
	local name="$1"
	shift
	local start rc
	start=$(date +%s)
	echo "INFO: [must-gather-sos] plugin ${name}: starting"
	"$@"
	rc=$?
	echo "${name} ${rc} $(($(date +%s) - start))" >>/must-gather/must-gather-sos-plugins.log
	echo "INFO: [must-gather-sos] plugin ${name}: finished rc=${rc}"
	return "${rc}"
}

pids=()

# --- core: base 'oc adm inspect' pass (upstream gather, inline) ---
named_resources=(ns/openshift-cluster-version ns/default ns/openshift ns/kube-system ns/openshift-etcd ns/assisted-installer)
group_resources=(clusterversion clusteroperators apiservices certificatesigningrequests nodes storageclasses persistentvolumes volumeattachments csidrivers csinodes volumesnapshotclasses volumesnapshotcontents volumegroupsnapshotclasses volumegroupsnapshotcontents clustercsidrivers volumeattributesclasses imagecontentsourcepolicies.operator.openshift.io imagedigestmirrorsets.config.openshift.io imagetagmirrorsets.config.openshift.io osimagestreams.machineconfiguration.openshift.io internalreleaseimages.machineconfiguration.openshift.io networks.operator.openshift.io pacemakerclusters.etcd.openshift.io prioritylevelconfigurations.flowcontrol.apiserver.k8s.io flowschemas.flowcontrol.apiserver.k8s.io clusterresourcequotas.quota.openshift.io)
all_ns_resources=(csistoragecapacities leases)

core_named() {
	# shellcheck disable=SC2086
	oc adm inspect ${log_collection_args} --dest-dir must-gather ${rotated_pod_logs_arg} "${named_resources[@]}"
}

core_groups() {
	local filtered=()
	local gr
	for gr in "${group_resources[@]}"; do
		if oc get "$gr" >/dev/null 2>&1; then
			filtered+=("$gr")
		fi
	done
	local text
	text=$(
		IFS=,
		echo "${filtered[*]}"
	)
	# shellcheck disable=SC2086
	oc adm inspect ${log_collection_args} --dest-dir must-gather ${rotated_pod_logs_arg} "${text}"
}

core_all_namespaces() {
	local text
	text=$(
		IFS=,
		echo "${all_ns_resources[*]}"
	)
	# shellcheck disable=SC2086
	oc adm inspect ${log_collection_args} --dest-dir must-gather ${rotated_pod_logs_arg} "${text}" --all-namespaces
}

run_plugin core:named core_named &
pids+=($!)
run_plugin core:groups core_groups &
pids+=($!)
run_plugin core:all-namespaces core_all_namespaces &
pids+=($!)

# --- parallel plugins ---
run_plugin service_logs /usr/bin/gather_service_logs master &
pids+=($!)

if [ ${#pids[@]} -ne 0 ]; then
	echo "Waiting on subprocesses to finish execution."
	wait "${pids[@]}"
fi

# Optionally compress collected log files before the sidecar copies them out.
# Enabled via --reduce-logs compress_logs.
if [ "${compress_after_gather}" = "true" ]; then
	compress_logs
fi

# Force disk flush so everything is visible to the copy container.
sync
